mapper.select:



		AND MENU_NAME like concat('%', #{menuName}, '%')


		AND VISIBLE = #{visible}


		AND STATUS = #{status}


order by PARENT_ID, ORDER_NUM

		select distinct m.MENU_ID, m.PARENT_ID, m.MENU_NAME, m.PATH, m.COMPONENT, m."QUERY", m.VISIBLE, m.STATUS, COALESCE(m.PERMS,'') as perms, m.IS_FRAME, m.IS_CACHE, m.MENU_TYPE, m.ICON, m.ORDER_NUM, m.CREATE_TIME
		from SYS_MENU m
		left join SYS_ROLE_MENU rm on m.MENU_ID = rm.MENU_ID
		left join SYS_USER_ROLE ur on rm.ROLE_ID = ur.ROLE_ID
		left join SYS_ROLE ro on ur.ROLE_ID = ro.ROLE_ID
		where ur.USER_ID = #{params.userId}

            AND m.MENU_NAME like concat('%', #{menuName}, '%')


            AND m.VISIBLE = #{visible}


            AND m.STATUS = #{status}

		order by m.PARENT_ID, m.ORDER_NUM

select m.MENU_ID from SYS_MENU m left join SYS_ROLE_MENU rm on m.MENU_ID = rm.MENU_ID where rm.ROLE_ID = #{roleId}
and m.MENU_ID not in (select m.PARENT_ID from SYS_MENU m inner join SYS_ROLE_MENU rm on m.MENU_ID = rm.MENU_ID and rm.ROLE_ID = #{roleId})
order by m.PARENT_ID, m.ORDER_NUM

mapper.update:
update SYS_MENU
MENU_NAME = #{menuName}, PARENT_ID = #{parentId}, ORDER_NUM = #{orderNum}, PATH = #{path}, COMPONENT = #{component}, "QUERY" = #{query}, IS_FRAME = #{isFrame}, IS_CACHE = #{isCache}, MENU_TYPE = #{menuType}, VISIBLE = #{visible}, STATUS = #{status}, PERMS = #{perms}, ICON = #{icon}, REMARK = #{remark}, UPDATE_BY = #{updateBy}, UPDATE_TIME = CURRENT_TIMESTAMP
where MENU_ID = #{menuId}
